def verify_isbn(isbn: str) -> str:
    # Remove hyphens to get the digits
    digits = isbn.replace('-', '')

    # Check if the length is 10
    if len(digits) != 10:
        raise ValueError("ISBN must be 10 characters long (excluding hyphens)")

    # Check if all characters are digits or the last one is 'X'
    for i, ch in enumerate(digits):
        if i < 9:
            if not ch.isdigit():
                raise ValueError(f"Character at position {i} is not a digit: {ch}")
        else:
            if ch != 'X' and not ch.isdigit():
                raise ValueError(f"Last character must be a digit or 'X': {ch}")

    # Calculate the checksum
    total = 0
    for i in range(10):
        if i < 9:
            total += int(digits[i]) * (10 - i)
        else:
            if digits[i] == 'X':
                total += 10 * 1
            else:
                total += int(digits[i]) * 1

    # Check if the checksum is valid
    if total % 11 == 0:
        return "Right"
    else:
        # Calculate the correct check digit
        remainder = total % 11
        # The check digit should be such that (total - old_check_digit + new_check_digit) % 11 == 0
        # Actually, we need to find the check digit d such that (sum of first 9 digits weighted + d) % 11 == 0
        # Let's recalculate: sum of first 9 digits weighted
        sum_first_9 = 0
        for i in range(9):
            sum_first_9 += int(digits[i]) * (10 - i)

        # We need (sum_first_9 + d) % 11 == 0
        # So d = (11 - (sum_first_9 % 11)) % 11
        d = (11 - (sum_first_9 % 11)) % 11

        if d == 10:
            check_char = 'X'
        else:
            check_char = str(d)

        # Reconstruct the ISBN with the correct check digit
        # The format is 'x-xxx-xxxxx-x'
        # So we need to replace the last character
        corrected_digits = digits[:9] + check_char
        corrected_isbn = f"{corrected_digits[0]}-{corrected_digits[1:4]}-{corrected_digits[4:9]}-{corrected_digits[9]}"

        return corrected_isbn
