def decode(encoded: str, original: str, message: str) -> str:
    # Check if lengths match
    if len(encoded) != len(original):
        return "Failed"

    # Build mapping from encoded to original
    mapping = {}
    # Also track which original letters are used to ensure bijection
    used_original = set()

    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            # If we've seen this encoded char before, it must map to the same original char
            if mapping[enc_char] != orig_char:
                return "Failed"
        else:
            # Check if this original char is already used by another encoded char
            if orig_char in used_original:
                return "Failed"
            mapping[enc_char] = orig_char
            used_original.add(orig_char)

    # Check if all 26 letters are represented in the mapping
    # The problem says "not all letters are represented in the mapping"
    # This likely means the mapping should cover all 26 uppercase letters
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded = []
    for char in message:
        if char in mapping:
            decoded.append(mapping[char])
        else:
            # If a character in the message is not in the mapping, we can't decode it
            return "Failed"

    return ''.join(decoded)
